28	final class RoundRobinStrategy implements EndpointSelectionStrategy {
29	
30	    static final RoundRobinStrategy INSTANCE = new RoundRobinStrategy();
31	
32	    private RoundRobinStrategy() {}
33	
34	    @Override
35	    public EndpointSelector newSelector(EndpointGroup endpointGroup) {
36	        return new RoundRobinSelector(endpointGroup);
37	    }
38	
39	    /**
40	     * A round robin select strategy.
41	     *
42	     * <p>For example, with node a, b and c, then select result is abc abc ...
43	     */
44	    static class RoundRobinSelector extends AbstractEndpointSelector {
45	        private final AtomicInteger sequence = new AtomicInteger();
46	
47	        RoundRobinSelector(EndpointGroup endpointGroup) {
48	            super(endpointGroup);
49	            initialize();
50	        }
51	
52	        @Nullable
53	        @Override
54	        public Endpoint selectNow(ClientRequestContext ctx) {
55	            final List<Endpoint> endpoints = group().endpoints();
56	            if (endpoints.isEmpty()) {
57	                return null;
58	            }
59	            final int currentSequence = sequence.getAndIncrement();
60	            return endpoints.get(Math.abs(currentSequence % endpoints.size()));
61	        }
62	
63	        @Override
64	        public String toString() {
65	            return MoreObjects.toStringHelper(this)
66	                              .add("endpoints", group().endpoints())
67	                              .toString();
68	        }
69	    }
70	}
