37	final class WeightedRoundRobinStrategy implements EndpointSelectionStrategy {
38	
39	    private static final Logger logger = LoggerFactory.getLogger(WeightedRoundRobinStrategy.class);
40	
41	    static final WeightedRoundRobinStrategy INSTANCE = new WeightedRoundRobinStrategy();
42	
43	    private WeightedRoundRobinStrategy() {}
44	
45	    @Override
46	    public EndpointSelector newSelector(EndpointGroup endpointGroup) {
47	        return new WeightedRoundRobinSelector(endpointGroup);
48	    }
49	
50	    /**
51	     * A weighted round robin select strategy.
52	     *
53	     * <p>For example, with node a, b and c:
54	     * <ul>
55	     *   <li>if endpoint weights are 1,1,1 (or 2,2,2), then select result is abc abc ...</li>
56	     *   <li>if endpoint weights are 1,2,3 (or 2,4,6), then select result is abcbcc(or abcabcbcbccc) ...</li>
57	     *   <li>if endpoint weights are 3,5,7, then select result is abcabcabcbcbccc abcabcabcbcbccc ...</li>
58	     * </ul>
59	     */
60	    private static final class WeightedRoundRobinSelector extends AbstractEndpointSelector {
61	
62	        private final AtomicInteger sequence = new AtomicInteger();
63	        @Nullable
64	        private volatile EndpointsAndWeights endpointsAndWeights;
65	
66	        WeightedRoundRobinSelector(EndpointGroup endpointGroup) {
67	            super(endpointGroup);
68	            initialize();
69	        }
70	
71	        @Override
72	        protected void updateNewEndpoints(List<Endpoint> endpoints) {
73	            boolean found = false;
74	            for (Endpoint endpoint : endpoints) {
75	                if (endpoint.weight() > 0) {
76	                    found = true;
77	                    break;
78	                }
79	            }
80	            if (!found) {
81	                logger.warn("No valid endpoint with weight > 0. endpoints: {}", toShortString(endpoints));
82	            }
83	
84	            final EndpointsAndWeights endpointsAndWeights = this.endpointsAndWeights;
85	            if (endpointsAndWeights == null || endpointsAndWeights.endpoints != endpoints) {
86	                this.endpointsAndWeights = new EndpointsAndWeights(endpoints);
87	            }
88	        }
89	
90	        @Nullable
91	        @Override
92	        public Endpoint selectNow(ClientRequestContext ctx) {
93	            final EndpointsAndWeights endpointsAndWeights = this.endpointsAndWeights;
94	            if (endpointsAndWeights == null) {
95	                // 'endpointGroup' has not been initialized yet.
96	                return null;
97	            }
98	            final int currentSequence = sequence.getAndIncrement();
99	            return endpointsAndWeights.selectEndpoint(currentSequence);
100	        }
101	
102	        // endpoints accumulation which are grouped by weight
103	        private static final class EndpointsGroupByWeight {
104	            final long startIndex;
105	            final int weight;
106	            final long accumulatedWeight;
107	
108	            EndpointsGroupByWeight(long startIndex, int weight, long accumulatedWeight) {
109	                this.startIndex = startIndex;
110	                this.weight = weight;
111	                this.accumulatedWeight = accumulatedWeight;
112	            }
113	        }
114	
115	        @Override
116	        public String toString() {
117	            return MoreObjects.toStringHelper(this)
118	                              .add("endpointsAndWeights", endpointsAndWeights)
119	                              .toString();
120	        }
121	
122	        //
123	        // In general, assume the weights are w0 < w1 < ... < wM where M = N - 1, N is number of endpoints.
124	        //
125	        // * The first part of result: (a0..aM)(a0..aM)...(a0..aM) [w0 times for N elements].
126	        // * The second part of result: (a1..aM)...(a1..aM) [w1 - w0 times for N - 1 elements].
127	        // * and so on
128	        //
129	        // In this way:
130	        //
131	        // * Total number of elements of first part is: X(0) = w0 * N.
132	        // * Total number of elements of second part is: X(1) = (w1 - w0) * (N - 1)
133	        // * and so on
134	        //
135	        // Therefore, to find endpoint for a sequence S = currentSequence % totalWeight, firstly we find
136	        // the part which sequence belongs, and then modular by the number of elements in this part.
137	        //
138	        // Accumulation function F:
139	        //
140	        // * F(0) = X(0)
141	        // * F(1) = X(0) + X(1)
142	        // * F(2) = X(0) + X(1) + X(2)
143	        // * F(i) = F(i-1) + X(i)
144	        //
145	        // We could easily find the part (which sequence S belongs) using binary search on F.
146	        // Just find the index k where:
147	        //
148	        //                               F(k) <= S < F(k + 1).
149	        //
150	        // So, S belongs to part number (k + 1), index of the sequence in this part is P = S - F(k).
151	        // Because part (k + 1) start at index (k + 1), and contains (N - k - 1) elements,
152	        // then the real index is:
153	        //
154	        //                              (k + 1) + (P % (N - k - 1))
155	        //
156	        // For special case like w(i) == w(i+1). We just group them all together
157	        // and mark the start index of the group.
158	        //
159	        private static final class EndpointsAndWeights {
160	            private final List<Endpoint> endpoints;
161	            private final boolean weighted;
162	            private final long totalWeight; // prevent overflow by using long
163	            private final List<EndpointsGroupByWeight> accumulatedGroups;
164	
165	            EndpointsAndWeights(Iterable<Endpoint> endpoints) {
166	
167	                // prepare immutable endpoints
168	                this.endpoints = Streams.stream(endpoints)
169	                                        .filter(e -> e.weight() > 0) // only process endpoint with weight > 0
170	                                        .sorted(Comparator.comparing(Endpoint::weight)
171	                                                          .thenComparing(Endpoint::host)
172	                                                          .thenComparingInt(Endpoint::port))
173	                                        .collect(toImmutableList());
174	                final long numEndpoints = this.endpoints.size();
