42	/**
43	 * A skeletal {@link EndpointSelector} implementation. This abstract class implements the
44	 * {@link #select(ClientRequestContext, ScheduledExecutorService)} method by listening to
45	 * the change events emitted by {@link EndpointGroup} specified at construction time.
46	 */
47	public abstract class AbstractEndpointSelector implements EndpointSelector {
48	
49	    private final EndpointGroup endpointGroup;
50	    private final ReentrantShortLock lock = new ReentrantShortLock();
51	    @GuardedBy("lock")
52	    private final Set<ListeningFuture> pendingFutures =
53	            new ObjectLinkedOpenCustomHashSet<>(IdentityHashStrategy.of());
54	
55	    /**
56	     * Creates a new instance that selects an {@link Endpoint} from the specified {@link EndpointGroup}.
57	     */
58	    protected AbstractEndpointSelector(EndpointGroup endpointGroup) {
59	        this.endpointGroup = requireNonNull(endpointGroup, "endpointGroup");
60	    }
61	
62	    /**
63	     * Returns the {@link EndpointGroup} being selected by this {@link EndpointSelector}.
64	     */
65	    protected final EndpointGroup group() {
66	        return endpointGroup;
67	    }
68	
69	    @SuppressWarnings("GuardedBy")
70	    @VisibleForTesting
71	    final Set<ListeningFuture> pendingFutures() {
72	        return pendingFutures;
73	    }
74	
75	    @Deprecated
76	    @Override
77	    public final CompletableFuture<Endpoint> select(ClientRequestContext ctx,
78	                                                    ScheduledExecutorService executor,
79	                                                    long timeoutMillis) {
80	        return select(ctx, executor);
81	    }
82	
83	    @Override
84	    public final CompletableFuture<Endpoint> select(ClientRequestContext ctx,
85	                                                    ScheduledExecutorService executor) {
86	        final Endpoint endpoint = selectNow(ctx);
87	        if (endpoint != null) {
88	            return UnmodifiableFuture.completedFuture(endpoint);
89	        }
90	
91	        final ListeningFuture listeningFuture = new ListeningFuture(ctx, executor);
92	        addPendingFuture(listeningFuture);
93	
94	        // The EndpointGroup have just been updated after adding ListeningFuture.
95	        if (listeningFuture.isDone()) {
96	            return listeningFuture;
97	        }
98	        if (endpointGroup.whenReady().isDone()) {
99	            final Endpoint endpoint0 = selectNow(ctx);
100	            if (endpoint0 != null) {
101	                // The EndpointGroup have just been updated before adding ListeningFuture.
102	                listeningFuture.complete(endpoint0);
103	                return listeningFuture;
104	            }
105	        }
106	
107	        final long selectionTimeoutMillis = endpointGroup.selectionTimeoutMillis();
108	        if (selectionTimeoutMillis == 0) {
109	            // A static EndpointGroup.
110	            return UnmodifiableFuture.completedFuture(null);
111	        }
112	
113	        // Schedule the timeout task.
114	        if (selectionTimeoutMillis < Long.MAX_VALUE) {
115	            final ScheduledFuture<?> timeoutFuture = executor.schedule(() -> {
116	                final EndpointSelectionTimeoutException ex =
117	                        EndpointSelectionTimeoutException.get(endpointGroup, selectionTimeoutMillis);
118	                ClientPendingThrowableUtil.setPendingThrowable(ctx, ex);
119	                // Don't complete exceptionally so that the throwable
120	                // can be handled after executing the attached decorators
121	                listeningFuture.complete(null);
122	            }, selectionTimeoutMillis, TimeUnit.MILLISECONDS);
123	            listeningFuture.timeoutFuture = timeoutFuture;
124	
125	            // Cancel the timeout task if listeningFuture is done already.
126	            // This guards against the following race condition:
127	            // 1) (Current thread) Timeout task is scheduled.
128	            // 2) ( Other thread ) listeningFuture is completed, but the timeout task is not cancelled
129	            // 3) (Current thread) timeoutFuture is assigned to listeningFuture.timeoutFuture, but it's too
130	            // late.
131	            if (listeningFuture.isDone()) {
132	                timeoutFuture.cancel(false);
133	            }
134	        }
135	
136	        return listeningFuture;
137	    }
138	
139	    /**
140	     * Initialize this {@link EndpointSelector} to listen to the new endpoints emitted by the
141	     * {@link EndpointGroup}. The new endpoints will be passed to {@link #updateNewEndpoints(List)}.
142	     */
143	    @UnstableApi
144	    protected final void initialize() {
145	        endpointGroup.addListener(this::refreshEndpoints, true);
146	    }
147	
148	    private void refreshEndpoints(List<Endpoint> endpoints) {
149	        // Allow subclasses to update the endpoints first.
150	        updateNewEndpoints(endpoints);
151	        lock.lock();
152	        try {
153	            pendingFutures.removeIf(ListeningFuture::tryComplete);
154	        } finally {
155	            lock.unlock();
156	        }
157	    }
158	
159	    /**
